UPDATE runtime_operations SET status='running',attempt=attempt+1,worker_id=?1,lease_token=?3,lease_expires_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER)+(?2*1000000),updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER),progress_percent=NULL,progress_stage=NULL,planned_artifact_count=NULL,delivered_artifact_count=0 WHERE id=?4 AND status='queued' AND available_at<=CAST(unixepoch('subsec') * 1000000 AS INTEGER) AND cancel_requested=0 AND attempt<max_attempts RETURNING id,attempt,lease_token,worker_id,request,cancel_requested,cache_bypassed,lease_expires_at;